add('duplicate-invoice-detector','finance','🧾','كاشف الفواتير المكررة والمشبوهة','يلتقط تكرار الرقم أو المبلغ والمورد وفواتير بمبالغ مدورة وتسلسل مفقود.',
 [F('d','الفواتير (رقم | مورد | مبلغ | تاريخ)','textarea','1001 | شركة الأمل | 5000 | 2026-11-01\n1002 | شركة الأمل | 5000 | 2026-11-02\n1003 | مؤسسة النور | 1234.5 | 2026-11-03\n1003 | مؤسسة النور | 1234.5 | 2026-11-04\n1006 | شركة الأمل | 10000 | 2026-11-05',r=7)],
 r'''function compute(v){const R=lines(v.d).map(r=>({n:r[0],s:r[1],a:num(r[2]),d:r[3]}));const fl=[];R.forEach((x,i)=>{R.forEach((y,j)=>{if(j<=i)return;if(x.n===y.n&&x.s===y.s)fl.push(['رقم ومورد مكرر',x.n+' / '+x.s,f(x.a)]);else if(x.s===y.s&&x.a===y.a)fl.push(['نفس المورد والمبلغ بأرقام مختلفة',x.n+' و '+y.n,f(x.a)])})});const rd=R.filter(x=>x.a>=1000&&x.a%1000===0).map(x=>['مبلغ مدوّر',x.n+' / '+x.s,f(x.a)]);const nums=R.map(x=>parseInt(x.n)).filter(x=>!isNaN(x)).sort((a,b)=>a-b),gap=[];for(let i=1;i<nums.length;i++)if(nums[i]-nums[i-1]>1)gap.push(['فجوة تسلسل',nums[i-1]+' → '+nums[i],'']);const all=fl.concat(rd,gap);return kpis([kpi('إشارات تحذير',all.length,all.length?'bad':'good')])+tbl(['النوع','التفاصيل','المبلغ'],all)+rec(['لا تدفع قبل مراجعة الفاتورة المكررة مع المورد.','فعّل المطابقة الثلاثية (أمر شراء + استلام + فاتورة).','المبالغ المدورة قد تدل على تقدير لا فاتورة حقيقية: اطلب مستندًا.'])}''')

add('trial-balance-checker','finance','⚖️','فاحص ميزان المراجعة ومصحح الفروق','يتحقق من توازن المدين والدائن ويقترح أسباب الفرق (عكس أرقام، خانة، قيد مفرد).',
 [F('t','الأرصدة (حساب | مدين | دائن)','textarea','النقدية | 50000 | 0\nالذمم المدينة | 30000 | 0\nالمخزون | 20000 | 0\nالموردون | 0 | 25000\nرأس المال | 0 | 70000\nالإيرادات | 0 | 45000\nالمصروفات | 40000 | 0',r=8)],
 r'''function compute(v){const R=lines(v.t).map(r=>({n:r[0],d:num(r[1]),c:num(r[2])})),D=R.reduce((s,x)=>s+x.d,0),C=R.reduce((s,x)=>s+x.c,0),diff=Math.round((D-C)*100)/100;const hints=[];if(Math.abs(diff)>0.005){if(Math.round(Math.abs(diff))%9===0)hints.push('الفرق يقبل القسمة على 9: ربما عكس أرقام (transposition) مثل 54 بدل 45.');if(Math.round(Math.abs(diff))%10===0)hints.push('الفرق من مضاعفات 10: ربما خطأ في خانة عشرية.');const eq=R.filter(x=>Math.abs(x.d+x.c-Math.abs(diff))<0.005);if(eq.length)hints.push('حساب بمبلغ الفرق نفسه: '+eq.map(x=>x.n).join('، ')+' (قد يكون قيدًا مفردًا أو ترحيلًا ناقصًا).');const half=R.filter(x=>Math.abs((x.d+x.c)-Math.abs(diff)/2)<0.005);if(half.length)hints.push('نصف الفرق يساوي رصيد '+half.map(x=>x.n).join('، ')+': قد يكون مرحّلًا بالجهة المعاكسة.');if(!hints.length)hints.push('راجع القيود غير المرحّلة والأرصدة الافتتاحية.')}return kpis([kpi('إجمالي المدين',f(D)),kpi('إجمالي الدائن',f(C)),kpi('الفرق',f(diff),diff?'bad':'good')])+(diff?'<h4>أسباب محتملة</h4>'+ol(hints):'<b>✅ الميزان متوازن.</b>')+rec(['التوازن لا يعني صحة الأرصدة: الأخطاء المتعادلة لا تظهر.','راجع الأرصدة غير المعتادة (ذمم دائنة، مخزون سالب).'])}'''+OL)

add('ar-ap-aging-report','finance','⏳','تقرير أعمار الذمم المدينة والدائنة','تصنيف الفواتير حسب التأخير مع مخصص مقترح وأولويات التحصيل.',
 [F('d','الفواتير (عميل | مبلغ | تاريخ الاستحقاق)','textarea','شركة أ | 12000 | 2026-10-01\nشركة ب | 8000 | 2026-11-10\nمؤسسة ج | 15000 | 2026-08-15\nشركة د | 5000 | 2026-11-30',r=6),F('t','تاريخ التقرير','date','2026-11-26')],
 r'''function compute(v){const R=lines(v.d).map(r=>{const days=Math.floor((new Date(v.t)-new Date(r[2]))/864e5);return{n:r[0],a:num(r[1]),dd:days}});const B=[['لم يستحق',x=>x.dd<=0,0],['1-30',x=>x.dd>0&&x.dd<=30,2],['31-60',x=>x.dd>30&&x.dd<=60,8],['61-90',x=>x.dd>60&&x.dd<=90,20],['+90',x=>x.dd>90,50]];const rows=B.map(b=>{const L=R.filter(b[1]),s=L.reduce((a,x)=>a+x.a,0);return[b[0],L.length,f(s),b[2]+'%',f(s*b[2]/100)]});const tot=R.reduce((a,x)=>a+x.a,0),pr=rows.reduce((a,r)=>a+num(String(r[4]).replace(/,/g,'')),0);return kpis([kpi('إجمالي الذمم',f(tot)),kpi('مخصص مقترح',f(pr),'bad')])+tbl(['الفئة','عدد','المبلغ','نسبة المخصص','المخصص'],rows)+'<h4>أولوية التحصيل</h4>'+tbl(['العميل','المبلغ','أيام التأخير'],R.filter(x=>x.dd>0).sort((a,b)=>b.a*b.dd-a.a*a.dd).map(x=>[x.n,f(x.a),x.dd]))+rec(['نسب المخصص افتراضية: اضبطها من تجربتك (IFRS 9).','تواصل شخصيًا مع كبار المتأخرين أولًا.'])}''')

add('three-way-match','finance','🔗','المطابقة الثلاثية: أمر شراء + استلام + فاتورة','اكتشف فروق الكمية والسعر قبل الدفع.',
 [F('d','البنود (صنف | كمية أمر الشراء | كمية مستلمة | كمية الفاتورة | سعر الأمر | سعر الفاتورة)','textarea','لابتوب | 10 | 10 | 10 | 3000 | 3000\nطابعة | 5 | 4 | 5 | 800 | 850\nشاشة | 8 | 8 | 8 | 600 | 600',r=5),F('tol','تسامح السعر %','n',1)],
 r'''function compute(v){let ex=0;const rows=lines(v.d).map(r=>{const [po,gr,iq,pp,ip]=[num(r[1]),num(r[2]),num(r[3]),num(r[4]),num(r[5])],q=iq>gr,p=Math.abs(ip-pp)/pp*100>v.tol;if(q)ex+=(iq-gr)*ip;if(p)ex+=(ip-pp)*iq;return[r[0],po,gr,iq,pp,ip,q?'🔴 فاتورة > استلام':p?'🟡 فرق سعر':'🟢 مطابق']});return tbl(['الصنف','أمر','استلام','فاتورة','سعر أمر','سعر فاتورة','الحالة'],rows)+kpis([kpi('مبلغ معرّض للدفع الزائد',f(ex),ex?'bad':'good')])+rec(['لا تعتمد الدفع للبنود الحمراء قبل تسوية مع المورد.','الفروق الصغيرة ضمن التسامح تُعتمد بتصريح.'])}''')

add('budget-vs-actual-variance','finance','📉','تحليل انحراف الموازنة عن الفعلي','انحرافات مطلقة ونسبية وأحكام وتوصيات لكل بند.',
 [F('d','البنود (بند | موازنة | فعلي | نوع: إيراد/مصروف)','textarea','المبيعات | 500000 | 460000 | إيراد\nالرواتب | 150000 | 158000 | مصروف\nالتسويق | 40000 | 52000 | مصروف\nالإيجار | 30000 | 30000 | مصروف',r=6)],
 r'''function compute(v){let nb=0;const rows=lines(v.d).map(r=>{const b=num(r[1]),a=num(r[2]),rev=r[3]==='إيراد',d=a-b,fav=rev?d>=0:d<=0,p=d/b*100;nb+=rev?d:-d;return[r[0],f(b),f(a),f(d),f(p,1)+'%',fav?'🟢 مواتٍ':Math.abs(p)>10?'🔴 غير مواتٍ جوهري':'🟡 غير مواتٍ']});return tbl(['البند','الموازنة','الفعلي','الانحراف','%','الحكم'],rows)+kpis([kpi('الأثر الصافي على الربح',f(nb),nb>=0?'good':'bad')])+rec(['حقق في الانحرافات فوق 10% أو التي تتكرر.','فرّق بين انحراف حجم وسعر وكفاءة.','حدّث التوقعات (rolling forecast) ربع سنويًا.'])+aiOut('اكتب تعليقًا إداريًا على انحرافات الموازنة: '+rows.map(r=>r[0]+' '+r[4]+' '+r[5]).join('؛'))}''')

add('cash-flow-statement-indirect','finance','💧','قائمة التدفقات النقدية (غير المباشرة) IAS 7','من صافي الربح إلى التدفقات التشغيلية والاستثمارية والتمويلية.',
 [F('np','صافي الربح','n',180000),F('dep','إهلاك واستنفاد','n',40000),F('ar','زيادة الذمم المدينة','n',25000),F('inv','زيادة المخزون','n',30000),F('ap','زيادة الذمم الدائنة','n',20000),F('cx','شراء أصول ثابتة','n',-120000),F('sa','بيع أصول','n',10000),F('ln','قروض مستلمة','n',100000),F('rp','سداد قروض','n',-40000),F('dv','توزيعات','n',-30000),F('op','نقد أول المدة','n',70000)],
 r'''function compute(v){const o=v.np+v.dep-v.ar-v.inv+v.ap,i=v.cx+v.sa,fn=v.ln+v.rp+v.dv,net=o+i+fn;return tbl(['البند','المبلغ'],[['صافي الربح',f(v.np)],['+ الإهلاك',f(v.dep)],['− زيادة الذمم المدينة',f(-v.ar)],['− زيادة المخزون',f(-v.inv)],['+ زيادة الذمم الدائنة',f(v.ap)],['<b>التدفق التشغيلي</b>',f(o)],['<b>التدفق الاستثماري</b>',f(i)],['<b>التدفق التمويلي</b>',f(fn)],['<b>صافي التغير في النقد</b>',f(net)],['نقد أول المدة',f(v.op)],['<b>نقد آخر المدة</b>',f(v.op+net)]])+rec([o<v.np?'التدفق التشغيلي أقل من الربح: راجع رأس المال العامل.':'التدفق التشغيلي يدعم الربح.',o<-i?'التشغيل لا يغطي الاستثمار: تعتمد على التمويل.':'التشغيل يغطي الاستثمار.'])}''')

add('fx-revaluation-ias21','finance','💱','إعادة تقييم العملات الأجنبية IAS 21','أرباح وخسائر فروق العملة للبنود النقدية.',
 [F('a','المبلغ بالعملة الأجنبية','n',50000),F('r1','سعر الصرف وقت المعاملة','n',3.75),F('r2','سعر الصرف في تاريخ التقرير','n',3.80),S('t','نوع البند',[('ar','ذمم مدينة/نقد (أصل)'),('ap','ذمم دائنة (التزام)')])],
 r'''function compute(v){const b0=v.a*v.r1,b1=v.a*v.r2,d=b1-b0,gain=v.t==='ar'?d:-d;return kpis([kpi('القيمة الأصلية',f(b0)),kpi('القيمة المعاد تقييمها',f(b1)),kpi(gain>=0?'ربح فروق عملة':'خسارة فروق عملة',f(Math.abs(gain)),gain>=0?'good':'bad')])+'<h4>القيد</h4>'+tbl(['الحساب','مدين','دائن'],[[v.t==='ar'?'الذمم المدينة/النقد':'الذمم الدائنة',gain>=0?f(Math.abs(d)):'',gain>=0?'':f(Math.abs(d))],[gain>=0?'ربح فروق عملة':'خسارة فروق عملة',gain>=0?'':f(Math.abs(gain)),gain>=0?f(Math.abs(gain)):'']])+rec(['البنود النقدية تُقيَّم بسعر الإقفال، وغير النقدية بالتكلفة التاريخية.','الفروق تُدرج في الأرباح والخسائر.'])}''')

add('zakat-base-estimator','finance','🕌','مقدّر وعاء الزكاة للمنشآت','تقدير وعاء الزكاة التقريبي بالطريقة المبسطة (تقديري).',
 [F('eq','حقوق الملكية والمصادر','n',2000000),F('ad','تعديلات تضاف (مخصصات، قروض طويلة)','n',300000),F('fa','أصول ثابتة وغير متداولة','n',900000),F('ot','حسومات أخرى','n',100000),F('p','صافي الربح المعدل','n',250000)],
 r'''function compute(v){const base=v.eq+v.ad-v.fa-v.ot,b2=Math.max(base,v.p),z=b2*0.025;return kpis([kpi('الوعاء المبدئي',f(base)),kpi('الوعاء (الأعلى مع الربح)',f(b2)),kpi('الزكاة بنسبة 2.5%',f(z),'good')])+note('تقدير مبسّط جدًا للتعلّم فقط. القواعد التفصيلية والتعديلات تخضع للوائح هيئة الزكاة والضريبة والجمارك؛ راجع محاسبًا قانونيًا.')+rec(['احتفظ بمستندات كل بند حسم.','الإقرار والسداد في المواعيد النظامية.'])}''')

add('fixed-asset-register','finance','🏗️','سجل الأصول الثابتة وجدول الإهلاك','سجل أصول بقيمها الدفترية الحالية وإهلاك الفترة.',
 [F('a','الأصول (اسم | تكلفة | سنة الشراء | عمر | خردة)','textarea','سيارة | 90000 | 2024 | 5 | 10000\nأجهزة | 40000 | 2025 | 4 | 0\nأثاث | 25000 | 2023 | 8 | 2000',r=6),F('y','سنة التقرير','n',2026)],
 r'''function compute(v){let tc=0,tn=0,td=0;const rows=lines(v.a).map(r=>{const c=num(r[1]),py=num(r[2]),l=num(r[3]),s=num(r[4]),yr=Math.min(l,Math.max(0,v.y-py+1)),dep=(c-s)/l,acc=dep*yr,nbv=c-acc;tc+=c;tn+=nbv;td+=py<=v.y&&yr<=l?dep:0;return[r[0],f(c),py,l,f(dep),f(acc),f(nbv)]});return tbl(['الأصل','التكلفة','سنة الشراء','العمر','إهلاك سنوي','مجمع','دفترية'],rows)+kpis([kpi('إجمالي التكلفة',f(tc)),kpi('القيمة الدفترية',f(tn),'good'),kpi('إهلاك السنة',f(td))])+rec(['اجرِ جردًا فعليًا للأصول سنويًا.','راجع العمر الإنتاجي والخردة.'])}''')

add('expense-smart-categorizer','finance','🏷️','مصنّف المصروفات الذكي','يصنّف بيانات المصروفات تلقائيًا إلى بنود المحاسبة المناسبة.',
 [F('d','المصروفات (بيان | مبلغ)','textarea','فاتورة كهرباء نوفمبر | 850\nراتب موظف | 7000\nإعلان سناب | 3000\nإيجار المكتب | 4000\nتذاكر سفر مندوب | 1200\nقرطاسية | 150\nبرنامج محاسبة اشتراك | 300',r=8)],
 r'''function compute(v){const C=[['مرافق','كهرباء|ماء|انترنت|إنترنت|هاتف'],['رواتب وأجور','راتب|رواتب|اجر|أجور|عمولة'],['تسويق وإعلان','اعلان|إعلان|سناب|تيك|جوجل|تسويق'],['إيجارات','ايجار|إيجار'],['سفر وتنقل','سفر|تذاكر|فندق|وقود|مواصلات'],['مستلزمات مكتبية','قرطاسية|ورق|حبر'],['برمجيات واشتراكات','برنامج|اشتراك|سحابي|ترخيص'],['صيانة','صيانة|اصلاح|إصلاح'],['رسوم حكومية وبنكية','رسوم|غرامة|بنك|مخالفة']];const sum={};const rows=lines(v.d).map(r=>{const c=C.find(x=>new RegExp(x[1]).test(r[0]));const k=c?c[0]:'غير مصنّف — راجع';sum[k]=(sum[k]||0)+num(r[1]);return[r[0],f(num(r[1])),k]});return tbl(['البيان','المبلغ','التصنيف'],rows)+'<h4>الملخص</h4>'+tbl(['التصنيف','المجموع'],Object.entries(sum).sort((a,b)=>b[1]-a[1]).map(x=>[x[0],f(x[1])]))+rec(['راجع البنود غير المصنفة يدويًا.','أضف مركز تكلفة لكل مشروع.'])}''')

add('accruals-prepayments-calculator','finance','🗓️','حاسبة المستحقات والمدفوعات المقدمة','تقسيم مصروف/إيراد على الفترات وقيود التسوية.',
 [F('a','المبلغ المدفوع','n',12000),F('s','تاريخ بداية التغطية','date','2026-10-01'),F('m','عدد الأشهر','n',12),F('c','تاريخ إقفال الدفاتر','date','2026-12-31')],
 r'''function compute(v){const s=new Date(v.s),c=new Date(v.c),el=Math.max(0,Math.min(v.m,(c.getFullYear()-s.getFullYear())*12+c.getMonth()-s.getMonth()+1)),mo=v.a/v.m,exp=mo*el,pre=v.a-exp;return kpis([kpi('مصروف الفترة',f(exp)),kpi('مدفوع مقدمًا (أصل)',f(pre),'good'),kpi('شهري',f(mo))])+'<h4>قيد التسوية</h4>'+tbl(['الحساب','مدين','دائن'],[['مصروف',f(exp),''],['مصروفات مدفوعة مقدمًا (إن كانت سجلت كأصل)','',f(exp)]])+rec(['إن سُجل كل المبلغ كمصروف فعدّل بقيد مدفوعات مقدمة بقيمة '+f(pre)+'.'])}''')

add('journal-entry-validator','finance','✅','مدقّق القيود اليومية','يتحقق من توازن القيود وملاحظات الجودة (وصف، حسابات حساسة، مبالغ مدورة).',
 [F('d','القيود (رقم | حساب | مدين | دائن | وصف)','textarea','J1 | النقدية | 5000 | 0 | تحصيل\nJ1 | الذمم المدينة | 0 | 5000 | تحصيل\nJ2 | مصروف متنوع | 3000 | 0 | \nJ2 | النقدية | 0 | 2900 | سداد',r=8)],
 r'''function compute(v){const R=lines(v.d).map(r=>({j:r[0],a:r[1],d:num(r[2]),c:num(r[3]),t:r[4]||''}));const g={};R.forEach(x=>{g[x.j]=g[x.j]||{d:0,c:0,r:[]};g[x.j].d+=x.d;g[x.j].c+=x.c;g[x.j].r.push(x)});const rows=Object.entries(g).map(([j,o])=>{const iss=[];if(Math.abs(o.d-o.c)>0.005)iss.push('غير متوازن بفرق '+f(o.d-o.c));if(o.r.some(x=>!x.t.trim()))iss.push('بدون وصف');if(o.r.some(x=>/متنوع|أخرى|اخرى/.test(x.a)&&(x.d>=2000||x.c>=2000)))iss.push('حساب «متنوع» بمبلغ كبير');if(o.d>=1000&&o.d%1000===0)iss.push('مبلغ مدوّر: تحقق من المستند');return[j,f(o.d),f(o.c),iss.length?'🔴 '+iss.join('؛ '):'🟢 سليم']});return tbl(['القيد','مدين','دائن','الملاحظات'],rows)+rec(['كل قيد يدوي يحتاج وصفًا ومستندًا وموافقة.','راجع القيود قرب الإقفال وخارج ساعات العمل.'])}''')

add('inventory-count-reconciliation','finance','📋','مطابقة الجرد الفعلي مع سجلات المخزون','فروق الكمية والقيمة وأسباب محتملة وقيد التسوية.',
 [F('d','الأصناف (صنف | رصيد النظام | الجرد الفعلي | تكلفة الوحدة)','textarea','لابتوب | 50 | 48 | 3000\nماوس | 200 | 205 | 40\nكرسي | 30 | 30 | 400',r=6)],
 r'''function compute(v){let net=0;const rows=lines(v.d).map(r=>{const s=num(r[1]),a=num(r[2]),c=num(r[3]),d=a-s,val=d*c;net+=val;return[r[0],s,a,d,f(val),d<0?'🔴 عجز':d>0?'🟡 زيادة':'🟢 مطابق']});return tbl(['الصنف','النظام','الفعلي','الفرق','قيمة الفرق','الحالة'],rows)+kpis([kpi('صافي فرق الجرد',f(net),net<0?'bad':'good')])+'<h4>قيد التسوية</h4>'+tbl(['الحساب','مدين','دائن'],[[net<0?'مصروف عجز مخزون':'المخزون',f(Math.abs(net)),''],[net<0?'المخزون':'إيراد زيادة مخزون','',f(Math.abs(net))]])+rec(['حقق في الأصناف ذات العجز الكبير قبل التسوية.','راجع قيود الاستلام والإرجاع قرب الجرد.'])}''')

add('loan-amortization-schedule','finance','🏧','جدول سداد القروض','قسط ثابت وجدول بالفائدة والأصل.',
 [F('p','أصل القرض','n',200000),F('r','الفائدة السنوية %','n',6),F('y','المدة (سنوات)','n',4)],
 r'''function compute(v){const n=Math.round(v.y*12),i=v.r/1200,pm=i?v.p*i/(1-Math.pow(1+i,-n)):v.p/n;let bal=v.p,rows=[],ti=0;for(let k=1;k<=n;k++){const int=bal*i,pr=pm-int;bal-=pr;ti+=int;if(k<=12||k%12===0||k===n)rows.push([k,f(pm),f(int),f(pr),f(Math.max(bal,0))])}return kpis([kpi('القسط الشهري',f(pm),'good'),kpi('إجمالي الفوائد',f(ti),'bad'),kpi('إجمالي السداد',f(pm*n))])+tbl(['القسط','المبلغ','فائدة','أصل','رصيد'],rows)+rec(['السداد المعجّل يوفر فوائد: جرّب دفعة إضافية.'])}''')

add('supplier-statement-reconciliation','finance','📨','مطابقة كشف حساب المورد','قارن كشف المورد بدفاترك لاكتشاف الفواتير والدفعات الناقصة.',
 [F('s','كشف المورد (مرجع | مبلغ)','textarea','INV-101 | 5000\nINV-102 | 3000\nINV-103 | 2000\nPAY-9 | -4000',r=5),F('b','دفاترك (مرجع | مبلغ)','textarea','INV-101 | 5000\nINV-103 | 2000\nPAY-9 | -3500',r=5)],
 r'''function compute(v){const S=lines(v.s).map(r=>({k:r[0],a:num(r[1])})),B=lines(v.b).map(r=>({k:r[0],a:num(r[1])}));const rows=[];S.forEach(x=>{const y=B.find(b=>b.k===x.k);if(!y)rows.push([x.k,f(x.a),'—','لم تُسجَّل عندك']);else if(Math.abs(y.a-x.a)>0.005)rows.push([x.k,f(x.a),f(y.a),'فرق مبلغ '+f(x.a-y.a)])});B.forEach(y=>{if(!S.find(x=>x.k===y.k))rows.push([y.k,'—',f(y.a),'غير موجودة عند المورد'])});const ss=S.reduce((a,x)=>a+x.a,0),sb=B.reduce((a,x)=>a+x.a,0);return kpis([kpi('رصيد المورد',f(ss)),kpi('رصيدك',f(sb)),kpi('الفرق',f(ss-sb),Math.abs(ss-sb)<0.01?'good':'bad')])+tbl(['المرجع','عند المورد','عندك','الملاحظة'],rows)+rec(['اطلب من المورد المستند الداعم للفروق.','سجّل الفواتير الناقصة بتاريخها الصحيح.'])}''')

add('sales-commission-calculator','sales','💰','حاسبة عمولات المبيعات (حسب الموديل والفرع والبائع)','اكتب (أو ارفع) المنتجات وموديلاتها ومبلغ عمولة الوحدة المباعة، ثم ارفع تقرير المبيعات (Excel/CSV): تتعرّف الأداة على الموديل داخل وصف الصنف وتحسب عمولة كل فرع وكل بائع وكل منتج وكل موديل.',
 [F('r','عمولة الموديلات (منتج | موديل | عمولة الوحدة المباعة | نسبة % اختياري) — اكتب * مكان الموديل لعمولة كل موديل آخر من المنتج','textarea','ثلاجات | RF-300 | 50\nثلاجات | RF-500 | 80\nغسالات | WM-7 | 30\nغسالات | * | 20\nمكيفات | AC-18 | 120',r=6),
  F('s','تقرير المبيعات (فرع | بائع | الصنف أو الموديل | كمية | مبلغ البيع | تاريخ) — يكفي أن يحتوي وصف الصنف على اسم الموديل','textarea','الرياض | أحمد | ثلاجة سامسونج RF-300 | 4 | 12000 | 2026-11-02\nالرياض | أحمد | غسالة LG WM-7 اوتوماتيك | 8 | 8000 | 2026-11-05\nالرياض | سارة | ثلاجة RF500 | 7 | 20000 | 2026-11-07\nجدة | خالد | مكيف AC-18 سبليت | 5 | 15000 | 2026-11-10\nجدة | خالد | غسالة WM-9 | 6 | 6000 | 2026-11-12\nجدة | منى | ثلاجة RF-300 | 3 | 9000 | 2026-11-15\nالدمام | يوسف | غسالة WM-7 | 10 | 9500 | 2026-11-18\nالرياض | أحمد | مكيف AC-18 | -1 | -2000 | 2026-11-20',r=9),
  F('d','عمولة وحدة افتراضية لموديل غير مدرج (ريال)','n',0),
  F('dp','نسبة افتراضية % لموديل غير مدرج','n',0),
  F('tr','شرائح مكافأة على إجمالي مبيعات البائع — اختياري (حد المبيعات | نسبة إضافية %)','textarea','',r=3),
  S('tm','طريقة الشرائح',[('b','نسبة على كل مبيعات البائع'),('m','نسبة على الجزء الأعلى من الحد فقط')]),
  F('mn','حد أدنى لمبيعات البائع لاستحقاق العمولة (ريال)','n',0),
  F('cp','سقف عمولة البائع (0 = بلا سقف)','n',0),
  S('rt','المرتجعات (كمية/مبلغ سالب)',[('d','تخصم من العمولة'),('i','تُتجاهل')])],
 r'''function compute(v){
const nz=t=>String(t).toLowerCase().replace(/[ً-ْـ]/g,'').replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/ى/g,'ي').replace(/[\s\-_\/.]+/g,'');const stem=t=>nz(t).replace(/ات$/,'').replace(/ه$/,'');
const isN=t=>/^[\d.,٠-٩٫٬\s%\-]+$/.test(String(t==null?'':t).trim())&&/[\d٠-٩]/.test(String(t));
const R={},RL=[];lines(v.r).forEach(x=>{let pr='',m,u,pc;if(x.length>=3&&!isN(x[1])){pr=String(x[0]).trim();m=String(x[1]).trim();u=x[2];pc=x[3]}else{m=String(x[0]).trim();u=x[1];pc=x[2]}if(!m)return;const star=m==='*'||m==='كل';const o={u:num(u||0),p:num(String(pc||0).replace('%','')),k:nz(m),ps:stem(pr),name:star?(pr+' (باقي الموديلات)'):m,prod:pr,star:star};R[o.name]=o;RL.push(o)});
RL.sort((a,b)=>b.k.length-a.k.length);
const tiers=lines(v.tr).map(x=>({t:num(x[0]),p:num(String(x[1]).replace('%',''))})).sort((a,b)=>a.t-b.t);
let S=lines(v.s).map(x=>({br:String(x[0]).trim(),sl:String(x[1]).trim(),m:String(x[2]).trim(),q:num(x[3]),a:num(x[4]),d:x[5]||''})).filter(x=>x.sl&&!isNaN(x.a)&&!isNaN(x.q));
if(v.rt==='i')S=S.filter(x=>x.q>=0&&x.a>=0);
const unk={};const rate=m=>{const n=nz(m);let h=RL.find(r=>!r.star&&r.k&&n===r.k)||RL.find(r=>!r.star&&r.k&&n.includes(r.k))||RL.find(r=>r.star&&r.ps&&n.includes(r.ps));if(h)return h;unk[m]=1;return{u:v.d||0,p:v.dp||0,name:m,prod:''}};
S.forEach(x=>{const r=rate(x.m);x.u=r.u;x.p=r.p;x.mk=r.name||x.m;x.pr=r.prod||'';x.c=x.q*r.u+x.a*r.p/100});
const grp=key=>{const o={};S.forEach(x=>{const k=key(x)||'—';const g=o[k]=o[k]||{q:0,a:0,c:0,n:0};g.q+=x.q;g.a+=x.a;g.c+=x.c;g.n++});return o};
const sel=grp(x=>x.sl),SL={};Object.keys(sel).forEach(k=>{const g=sel[k];let bonus=0,tier='—';if(tiers.length){if(v.tm==='b'){const hit=tiers.filter(t=>g.a>=t.t).pop();if(hit){bonus=g.a*hit.p/100;tier='≥ '+f(hit.t,0)+' (+'+hit.p+'%)'}}else tiers.forEach((t,i)=>{if(g.a>t.t){const up=Math.min(g.a,i+1<tiers.length?tiers[i+1].t:Infinity);bonus+=(up-t.t)*t.p/100;tier='≥ '+f(t.t,0)}})}
let tot=g.c+bonus,note='';if(g.a<v.mn){tot=0;note='لم يبلغ الحد الأدنى';bonus=0}if(v.cp>0&&tot>v.cp){tot=v.cp;note='طُبّق السقف'}SL[k]={tot:tot,bonus:bonus,tier:tier,note:note}});
const brOf={};S.forEach(x=>{brOf[x.sl]=brOf[x.sl]||{};brOf[x.sl][x.br]=(brOf[x.sl][x.br]||0)+x.a});
const tS=S.reduce((s,x)=>s+x.a,0),tQ=S.reduce((s,x)=>s+x.q,0),tL=Object.values(SL).reduce((s,x)=>s+x.tot,0);
const slRows=Object.keys(sel).sort((a,b)=>SL[b].tot-SL[a].tot).map(k=>{const g=sel[k],r=SL[k];const br=Object.keys(brOf[k]).sort((a,b)=>brOf[k][b]-brOf[k][a])[0];return[k,br,g.q,f(g.a),f(g.c),r.tier,f(r.bonus),'<b>'+f(r.tot)+'</b>',r.note]});
const bg=grp(x=>x.br),brRows=Object.keys(bg).sort((a,b)=>bg[b].c-bg[a].c).map(k=>{const g=bg[k];const bonus=Object.keys(SL).reduce((s,sl)=>{const tot=Object.values(brOf[sl]).reduce((a,b)=>a+b,0)||1;return s+(brOf[sl][k]?SL[sl].bonus*brOf[sl][k]/tot:0)},0);const sellers=new Set(S.filter(x=>x.br===k).map(x=>x.sl)).size;return[k,sellers,g.q,f(g.a),f(g.c),f(bonus),'<b>'+f(g.c+bonus)+'</b>',f(g.a?(g.c+bonus)/g.a*100:0,2)+'%']});
const mg=grp(x=>x.mk||x.m),mrows=Object.keys(mg).sort((a,b)=>mg[b].c-mg[a].c).map(k=>{const g=mg[k],r=R[k];return[k,g.q,f(g.a),r?f(r.u):'<span style="color:#c33">غير مدرج</span>',r?(r.p?r.p+'%':'—'):'—',f(g.c),f(tS?g.a/tS*100:0,1)+'%']});
const bs=grp(x=>x.br+'|'+x.sl),bsRows=Object.keys(bs).sort().map(k=>{const a=k.split('|');return[a[0],a[1],bs[k].q,f(bs[k].a),f(bs[k].c)]});
const brs=Object.keys(bg),sls=Object.keys(sel),mat=sls.map(sl=>[sl].concat(brs.map(b=>{const x=S.filter(y=>y.sl===sl&&y.br===b).reduce((s,y)=>s+y.c,0);return x?f(x):'—'}),[f(sel[sl].c)]));
const bm=Object.keys(mg).map(m=>[m].concat(brs.map(b=>{const x=S.filter(y=>(y.mk||y.m)===m&&y.br===b);const q=x.reduce((s,y)=>s+y.q,0);return q?q+' = '+f(x.reduce((s,y)=>s+y.c,0)):'—'})));
const mons=grp(x=>String(x.d).slice(0,7)),monRows=Object.keys(mons).sort().map(k=>[k,mons[k].q,f(mons[k].a),f(mons[k].c)]);
const pgp=grp(x=>x.pr||'غير مصنّف'),pRows=Object.keys(pgp).sort((a,b)=>pgp[b].c-pgp[a].c).map(k=>[k,new Set(S.filter(x=>(x.pr||'غير مصنّف')===k).map(x=>x.mk||x.m)).size,pgp[k].q,f(pgp[k].a),f(pgp[k].c),f(tS?pgp[k].a/tS*100:0,1)+'%']);const pks=Object.keys(pgp),spm=sls.map(sl=>[sl].concat(pks.map(pk=>{const x=S.filter(y=>y.sl===sl&&(y.pr||'غير مصنّف')===pk);const q=x.reduce((a,y)=>a+y.q,0);return q?q+' = '+f(x.reduce((a,y)=>a+y.c,0)):'—'})));const unkList=Object.keys(unk);const topS=slRows[0],topB=brRows[0];
return kpis([kpi('إجمالي المبيعات',f(tS)),kpi('إجمالي الكمية',f(tQ,0)),kpi('إجمالي العمولات',f(tL),'good'),kpi('بائعون',sls.length),kpi('فروع',brs.length),kpi('أعلى بائع',topS?topS[0]:'—'),kpi('أعلى فرع',topB?topB[0]:'—')])
+(unkList.length?note('⚠️ أصناف في التقرير لم تتطابق مع أي موديل في قائمة العمولات (تأكد أن اسم الموديل مكتوب كما يظهر في الصنف): '+unkList.join('، ')+'. أضفها في خانة عمولة كل موديل.'):'')
+'<h4>عمولة كل بائع</h4>'+tbl(['البائع','الفرع الرئيسي','الكمية','المبيعات','عمولة الموديلات','الشريحة','مكافأة','إجمالي المستحق','ملاحظة'],slRows)
+'<h4>عمولة كل فرع</h4>'+tbl(['الفرع','عدد البائعين','الكمية','المبيعات','عمولة الموديلات','مكافآت','إجمالي العمولة','% من المبيعات'],brRows)
+'<h4>عمولة كل منتج</h4>'+tbl(['المنتج','عدد الموديلات المباعة','الكمية','المبيعات','إجمالي العمولة','حصة من المبيعات'],pRows)
+'<h4>البائع × المنتج (كمية = عمولة)</h4>'+tbl(['البائع'].concat(pks),spm)
+'<h4>عمولة كل موديل</h4>'+tbl(['الموديل','الكمية','المبيعات','عمولة الوحدة','النسبة','إجمالي العمولة','حصة من المبيعات'],mrows)
+'<h4>الفرع × البائع</h4>'+tbl(['الفرع','البائع','الكمية','المبيعات','العمولة'],bsRows)
+'<h4>مصفوفة عمولة البائع × الفرع</h4>'+tbl(['البائع'].concat(brs,['الإجمالي']),mat)
+'<h4>الموديل × الفرع (كمية = عمولة)</h4>'+tbl(['الموديل'].concat(brs),bm)
+(monRows.length>1?'<h4>العمولة شهريًا</h4>'+tbl(['الشهر','الكمية','المبيعات','العمولة'],monRows):'')
+'<h4>تفاصيل كل عملية</h4>'+tbl(['الفرع','البائع','الصنف في التقرير','الموديل المطابق','الكمية','المبلغ','عمولة الوحدة','النسبة','العمولة','التاريخ'],S.map(x=>[x.br,x.sl,x.m,(unk[x.m]?'<span style="color:#c33">غير مطابق</span>':x.mk),x.q,f(x.a),f(x.u),x.p?x.p+'%':'—',f(x.c),x.d]))
+rec([unkList.length?'أضف الموديلات الناقصة في قائمة العمولات لتكتمل الحسبة.':'كل الموديلات لها عمولة معرّفة.','العمولة = الكمية × عمولة الموديل (+ نسبة من قيمة البيع إن حدّدتها).','اربط صرف العمولة بالتحصيل الفعلي لتقليل الديون المعدومة.','اعتمد التقرير من المدير قبل الصرف، وصدّره Excel/PDF من الأزرار أعلاه.'])
+aiOut('راجع خطة عمولات المبيعات واقترح تحسينًا للعدالة والتحفيز: '+JSON.stringify({sellers:slRows.map(r=>[r[0],r[2],r[7]]),branches:brRows.map(r=>[r[0],r[6]]),models:mrows.map(r=>[r[0],r[3]])}))}''')
